'use strict';
(async()=>{const d=await(await fetch('research-data.json',{cache:'no-cache'})).json(),mk=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n},fmt=n=>Number(n||0).toLocaleString();const metrics=document.querySelector('#researchMetrics');[[d.records,'Catalogue records screened'],[d.sourceVerification?.linked,'Records linked to external sources'],[d.sourceVerification?.verified,'Verified edition connections'],[d.expansion?.qualitativeRarityRecords,'Source-attributed rarity assessments']].forEach(([n,l])=>{const e=mk('div');e.append(mk('b',fmt(n)),mk('span',l));metrics.append(e)});window.renderSourceCoverage?.(d.sourceVerification);const books=d.bookResearch||{},authors=d.authorResearch||{},expanded=d.expansion||{};document.querySelector('#scope').textContent='Research checked '+d.checked+'. Every catalogue record was included in the broad matching pass. Candidate coverage is intentionally generous; records with no plausible match remain unresolved. The expanded pass checked tentative sources, compared historical editions individually and added a specialist edition bibliography. The newest pass rechecked every original card for printing and format evidence, repaired OCR for source matching, and added scientific-article and journal leads. Scarcity labels remain attributed, low-confidence judgments; they do not supply worldwide copy totals.';const full=d.fullCataloguePass||{};const rows=[...(d.deepResearchPass?[["Latest detailed research",fmt(d.deepResearchPass.reviewedRecords)+' individual reviews / '+fmt(d.deepResearchPass.newVerifiedEditions)+' newly verified editions',fmt(d.deepResearchPass.newRarityRecords)+' additional records now have survival evidence. Located-copy minimums are distinct from estimates of the worldwide total.']]:[]),['Full catalogue reassessment',fmt(full.screened||d.records)+' records','Every original OCR card checked for format, printing and completeness clues, then screened against reference corpora. This is a full screening, not an individual web search or physical-copy inspection for every record.'],['Article and journal expansion',fmt(full.articleCorpusRecords)+' article reference records; '+fmt(full.containerRecords)+' journal / volume leads','Journal sources are kept separate from exact article, offprint and edition matches. Survival of a bound journal does not establish survival of the separate offprint.'],['Catalogue format clues',fmt(full.offprintRecords)+' records with offprint wording','Clues guide the next research step. A format, an old date, a limited print run or an unsuccessful search does not itself establish the number of surviving copies.'],['Rarity / survival evidence',fmt(full.rarityEvidenceRecords||305)+' records','This is the evidence subset shown by the rarity filter, not the number of records screened. All other records remain visible in the full view.'],['Catalogue transcription',fmt(d.records)+' records','All scanned pages retained, including papers, continuations and cross-references. These are not deduplicated books.'],['Recovered author headings',fmt(d.attribution?.previously_unattributed)+' previously unattributed records','Additional OCR-derived links, each carrying a confidence label.'],['Author identities',fmt(d.authorBiographies)+' of '+fmt(d.authorEntries)+' name entries','Public biographies or structured descriptions for proposed identities; variants can represent the same person.'],['Public book comparison',fmt(books.corpusRecords)+' reference records','Scientific and historical catalogue metadata screened locally; selected sources and dates limit coverage.'],['External source links',fmt(d.sourceVerification?.linked)+' family records','Includes verified editions, approximate references and low-confidence bibliography leads.'],['Candidate source refresh',fmt(expanded.candidateRecordsRefreshed)+' family records / '+fmt(expanded.sourceRecordsRetrieved)+' source records','Live metadata retrieved and identifiers checked; retrieval alone does not verify the edition.'],['Individual edition reviews',fmt(full.individualReviews||expanded.individualEditionReviews)+' records; '+fmt(d.sourceVerification?.verified)+' total verified','Title, author, year, imprint, extent and volume scope compared where available. Conflicting printings remain visible.'],['Additional edition bibliography',fmt(expanded.bibliographyEditionsScreened)+' editions screened','Schuh’s historical mineralogical bibliography; all family records screened, with links retained only where a plausible connection emerged.'],['Attributed rarity assessments',fmt(expanded.qualitativeRarityRecords)+' records','Low-confidence qualitative judgments, kept separate from numerical survival evidence. The bibliography favors scarce books, so its coverage is not representative.'],['Reference images',fmt(d.bookImages)+' book records; '+fmt(d.authorImages)+' author entries','Institutional galleries and public previews, with edition/identity and image confidence kept separate.'],['Unattributed after this pass',fmt(d.unattributed)+' catalogue records','Some are institutional, anonymous, incomplete, or lack a readable person heading.'],['Edition-specific survival research',fmt(d.survivalRecords)+' records','Published censuses, documented source-copy floors and conditional print-run bounds. At least one located copy is not proof of rarity.']];rows.forEach(values=>{const tr=mk('tr');values.forEach(v=>tr.append(mk('td',v)));document.querySelector('#coverageRows').append(tr)});(d.survivalHighlights||[]).forEach(e=>{const card=mk('article');card.className='reference-candidate';const a=mk('a',e.title);a.href='book.html?id='+e.id;const h=mk('h3');h.append(a);card.append(h,mk('p',e.summary));document.querySelector('#survivalHighlights').append(card)});document.querySelector('#checked').textContent='Last research pass: '+d.checked+'. Full provenance is available in the linked entries.'})().catch(e=>{document.querySelector('#scope').textContent='Coverage figures could not load. Please refresh.';console.error(e)});
